css:
h1 {
           color: #822fa4;
       }
       .header, .items, .totals, .terms {
           margin-bottom: 30px;
       }
       .header {
           display: flex;
           justify-content: space-between;
           align-items: center;
       }
       .header img {
           height: 80px;
       }
       .header-details {
           font-size: 14px;
       }
       .billed-table {
           width: 100%;
           margin-bottom: 30px;
           border-collapse: separate;
           border-spacing: 5px;
       }
       .billed-table .billed-box {
           background: #f3f0fb;
           padding: 10px;
           font-size: 14px;
           border-radius: 8px;
           vertical-align: top;
           width: 48%;
       }
       table {
           width: 100%;
           border-collapse: collapse;
           font-size: 14px;
       }
       thead {
           background: #822fa4;
           /*color: #fff;*/
       }
       th, td {
           padding: 10px;
           text-align: left;
           border: 1px solid #ccc;
       }
       .items tbody tr:nth-child(2) td {
           border-top: none;
       }
       .totals td {
           padding: 5px 10px;
       }
       .totals .label {
           text-align: right;
           width: 80%;
       }
       .totals .amount {
           text-align: right;
       }
       .totals .total {
           font-weight: bold;
           font-size: 16px;
           padding-top: 10px;
       }
       .terms {
           font-size: 12px;
       }
       .terms span {
           color: #822fa4;
       }
